package e.e.a;import android.preference.*;public class PatchInfoTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){PreferenceActivity a=new PreferenceActivity();PreferenceGroup about=new PreferenceGroup(a);about.setKey("about");a.getPreferenceScreen().addPreference(about);Preference version=PatchInfo.ensure(a,"v1.8.4-dev.1 @chikuwadon");check(a.findPreference("nicoid_patch_version")==version,"Version row restored for older XML");check(about.entries.contains(version),"Version remains in app information");check(version.getTitle().equals("パッチバージョン"),"Visible title");check(version.getSummary().equals("v1.8.4-dev.1 @chikuwadon"),"Current version shown");check(PatchInfo.ensure(a,"v1.8.4 @chikuwadon")==version&&about.entries.size()==1,"Repeated setup does not duplicate the row");check(version.getSummary().equals("v1.8.4 @chikuwadon"),"Existing row updated after version change");PreferenceActivity noAbout=new PreferenceActivity();check(PatchInfo.ensure(noAbout,"v1.8.4")!=null&&noAbout.findPreference("nicoid_patch_version")!=null,"Fallback works without app-information group");System.out.println("Version information restoration: 7 missing/existing/update/category checks passed");}}
